/bin/zsh -lc "NODE_USE_SYSTEM_CA=0 node --experimental-strip-types --input-type=module <<'EOF'
import assert from 'node:assert/strict';
import { CITIES, DEFAULT_CITY_IDS } from './src/lib/cities.ts';
import { buildSchedules, isAwake, rangesFromHours, utcOffset, formatTime, formatOffset } from './src/lib/time.ts';
import { loadState, saveState, DEFAULT_STATE, STORAGE_KEY } from './src/lib/storage.ts';
const date = new Date('2026-09-30T12:00:00Z');
const cities = DEFAULT_CITY_IDS.map(id => CITIES.find(city => city.id === id));
const settings = { wake: 7, sleep: 23, format: '12h' };
const meeting = buildSchedules(cities, settings, 'meeting', date);
const hours = schedule => schedule.overlap.flatMap((value, hour) => value ? [hour] : []);
assert.deepEqual(hours(meeting[0]), [7, 22]);
assert.deepEqual(rangesFromHours(meeting[0].overlap), [{ start: 7, end: 8 }, { start: 22, end: 23 }]);
assert(meeting.every(schedule => JSON.stringify(schedule.overlap) === JSON.stringify(meeting[0].overlap)));
assert.equal(meeting[1].minutes[7], 1320);
const base = buildSchedules(cities, settings, 'base', date);
assert.deepEqual(hours(base[1]), [7, 16, 17, 18, 19, 20, 21, 22]);
assert.deepEqual(hours(base[2]), [7, 8, 9, 10, 11, 12, 13, 22]);
assert.notDeepEqual(hours(base[1]), hours(base[2]));
assert(isAwake(22 * 60, 22, 6));
assert(isAwake(5 * 60 + 59, 22, 6));
assert("'!isAwake(6 * 60, 22, 6));
assert(!isAwake(12 * 60, 22, 6));
assert(isAwake(0, 7, 7));
assert.deepEqual(rangesFromHours(Array(24).fill(true)), [{ start: 0, end: 24 }]);
assert.deepEqual(rangesFromHours(Array(24).fill(false)), []);
assert.equal(utcOffset('"'America/Los_Angeles', new Date('2026-01-15T12:00:00Z')), -480);
assert.equal(utcOffset('America/Los_Angeles', new Date('2026-07-15T12:00:00Z')), -420);
assert.equal(utcOffset('Europe/Zurich', new Date('2026-01-15T12:00:00Z')), 60);
assert.equal(utcOffset('Europe/Zurich', new Date('2026-07-15T12:00:00Z')), 120);
assert.equal(utcOffset('Asia/Kolkata', date), 330);
assert.equal(utcOffset('Asia/Kathmandu', date), 345);
const fractional = buildSchedules([cities[0], CITIES.find(city => city.id === 'mumbai'), CITIES.find(city => city.id === 'kathmandu')], settings, 'meeting', date);
assert.equal(fractional[1].minutes[0], 750);
assert.equal(fractional[2].minutes[0], 765);
assert.equal(formatTime(750, '12h'), '12:30pm');
assert.equal(formatTime(765, '24h'), '12:45');
assert.equal(formatTime(1440, '12h'), '12am');
assert.equal(formatOffset(345), 'UTC+5:45');
assert.equal(formatOffset(-210), 'UTC−3:30');
assert.equal(CITIES.length, 34);
assert(CITIES.every(city => Number.isFinite(utcOffset(city.timezone, date))));
assert.deepEqual(buildSchedules([], settings, 'meeting', date), []);
const reordered = buildSchedules([cities[1], cities[0], cities[2]], settings, 'meeting', date);
assert.deepEqual(reordered[0].minutes, Array.from({ length: 24 }, (_, index) => index * 60));
let stored = null;
globalThis.localStorage = { getItem: () => stored, setItem: (key, value) => { assert.equal(key, STORAGE_KEY); stored = value; } };
assert.deepEqual(loadState(), DEFAULT_STATE);
const custom = { cityIds: ['kathmandu', 'mumbai'], mode: 'base', settings: { wake: 22, sleep: 6, format: '24h' } };
assert(saveState(custom));
assert.deepEqual(loadState(), custom);
stored = JSON.stringify({ cityIds: ['mumbai', 'mumbai', 'unknown'], mode: 'invalid', settings: { wake: -1, sleep: 24, format: 'invalid' } });
assert.deepEqual(loadState(), { cityIds: ['mumbai'], mode: 'meeting', settings: { wake: 7, sleep: 23, format: '12h' } });
stored = 'corrupted data';
assert.deepEqual(loadState(), DEFAULT_STATE);
globalThis.localStorage.setItem = () => { throw new Error('storage unavailable'); };
assert.equal(saveState(custom), false);
console.log('PASS: 39 assertions covering default overlap, independent base windows, overnight schedules, DST, fractional offsets, reference changes, catalog, and persistence.');
EOF"

